using System;

public class TwoDimensionalArraySearch
{
    public (int, int) SearchValue(int[,] arr, int target)
    {
        int rows = arr.GetLength(0);
        int cols = arr.GetLength(1);

        int start = 0;
        int end = rows * cols - 1;

        while (start <= end)
        {
            int mid = (start + end) / 2;
            int midRow = mid / cols;
            int midCol = mid % cols;

            int midValue = arr[midRow, midCol];

            if (midValue == target)
            {
                return (midRow, midCol);
            }
            else if (midValue < target)
            {
                start = mid + 1;
            }
            else
            {
                end = mid - 1;
            }
        }

        return (-1, -1);
    }

    public int SearchRow(int[,] arr, int target)
    {
        int rows = arr.GetLength(0);
        int cols = arr.GetLength(1);

        int start = 0;
        int end = rows - 1;

        while (start <= end)
        {
            int mid = (start + end) / 2;

            if (arr[mid, 0] <= target && target <= arr[mid, cols - 1])
            {
                int colIndex = Array.BinarySearch<int>(arr, mid * cols, cols, target);

                if (colIndex >= 0)
                {
                    return mid;
                }
            }

            if (target < arr[mid, 0])
            {
                end = mid - 1;
            }
            else
            {
                start = mid + 1;
            }
        }

        return -1;
    }

    public int SearchColumn(int[,] arr, int target)
    {
        int rows = arr.GetLength(0);
        int cols = arr.GetLength(1);

        int start = 0;
        int end = cols - 1;

        while (start <= end)
        {
            int mid = (start + end) / 2;

            if (arr[0, mid] <= target && target <= arr[rows - 1, mid])
            {
                for (int i = 0; i < rows; i++)
                {
                    if (arr[i, mid] == target)
                    {
                        return mid;
                    }
                }
            }

            if (target < arr[0, mid])
            {
                end = mid - 1;
            }
            else
            {
                start = mid + 1;
            }
        }

        return -1;
    }

    public (int, int) SearchSubmatrix(int[,] arr, int[,] submatrix)
    {
        int rows = arr.GetLength(0);
        int cols = arr.GetLength(1);
        int subRows = submatrix.GetLength(0);
        int subCols = submatrix.GetLength(1);

        for (int i = 0; i <= rows - subRows; i++)
        {
            for (int j = 0; j <= cols - subCols; j++)
            {
                bool found = true;

                for (int k = 0; k < subRows; k++)
                {
                    for (int l = 0; l < subCols; l++)
                    {
                        if (arr[i + k, j + l] != submatrix[k, l])
                        {
                            found = false;
                            break;
                        }
                    }

                    if (!found)
                    {
                        break;
                    }
                }

                if (found)
                {
                    return (i, j);
                }
            }
        }

        return (-1, -1);
    }
}
